def check_linear_correctly(a):
    for p in range(len(a)):
        if p + 1 >= len(a):
            break
        idx1 = a[p]
        if idx1 >= len(a):
            print(f"idx1 out of bounds at p={p}")
            return False
        idx2 = a[idx1]
        if idx2 >= len(a):
            print(f"idx2 out of bounds at p={p}")
            return False
        idx3 = a[idx2]
        if idx3 >= len(a):
            print(f"idx3 out of bounds at p={p}")
            return False

        print(f"p={p}: a[a[a[p]]]={idx3}, a[p+1]+1={a[p+1]+1}")
        if idx3 != a[p+1] + 1:
            return False
    return True

a_linear = [i + 1 for i in range(200)]
check_linear_correctly(a_linear)
